const FONT_ML400 = "";
const FONT_ML700 = "";
const FONT_OSW600 = "";
const FONT_OSW700 = "";

/* register embedded fonts before any canvas text is drawn */
async function registerFonts() {
  try {
    const faces = [
      ['NotoMal', FONT_ML400, '400'],
      ['NotoMal', FONT_ML700, '700'],
      ['Oswald', FONT_OSW600, '600'],
      ['Oswald', FONT_OSW700, '700']
    ];
    await Promise.all(faces.map(([fam, b64, w]) => {
      const bin = atob(b64);
      const buf = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
      return new FontFace(fam, buf.buffer, { weight: w, style: 'normal' }).load()
        .then(f => document.fonts.add(f)).catch(() => {});
    }));
    await document.fonts.ready;
    return true;
  } catch (e) { console.warn('font load failed', e); return false; }
}
